#[inline]
pub fn lil_list_to_value(
    mut list: lil_list_t,
    mut do_escape: c_int,
) -> lil_value_t { unsafe {
    let val: lil_value_t = alloc_value(::core::ptr::null::<c_char>());
    let count = (*list).c;
    let items = (*list).v;
    let escape_enabled = do_escape != 0;

    let mut i: size_t = 0;
    while i < count {
        let item = *items.add(i as usize);
        if i != 0 {
            lil_append_char(val, ' ' as i32 as c_char);
        }

        let escape: c_int = if escape_enabled {
            needs_escape(lil_to_string(item))
        } else {
            0 as c_int
        };

        if escape != 0 {
            lil_append_char(val, '{' as i32 as c_char);

            let item_ref = &*item;
            let len = item_ref.l;
            let data = item_ref.d;

            let mut j: size_t = 0;
            while j < len {
                let ch = *data.add(j as usize);
                if ch as c_int == '{' as i32 {
                    lil_append_string(val, b"}\"\\o\"{\0" as *const u8 as *const c_char);
                } else if ch as c_int == '}' as i32 {
                    lil_append_string(val, b"}\"\\c\"{\0" as *const u8 as *const c_char);
                } else {
                    lil_append_char(val, ch);
                }
                j = j.wrapping_add(1);
            }

            lil_append_char(val, '}' as i32 as c_char);
        } else {
            lil_append_val(val, item);
        }

        i = i.wrapping_add(1);
    }

    return val;
} }

